const { records, owners } = await ctx.call("records", {});
const totals = Object.fromEntries(owners.map(owner => [owner, 0]));
for (const record of records) {
  if (record.active && Object.hasOwn(totals, record.group)) {
    totals[record.group] += record.value;
  }
}
ctx.done(totals);
